const limits={file:12*1024*1024,pixels:12_000_000,projects:12,floors:12,versions:100,objects:200,events:1000};
function toast(text,warn=false){const n=document.createElement('div');n.className='toast'+(warn?' warn':'');n.textContent=text;$('toasts').append(n);setTimeout(()=>n.remove(),4500)}
function event(pr,type,text,detail={}){pr.events.push({id:uid('event'),time:now(),type,text,detail});if(pr.events.length>limits.events)pr.events.shift();saveSoon()}
async function img(url){if(images.has(url))return images.get(url);const task=new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('图片读取失败'));im.src=url});images.set(url,task);return task}
function synthetic(f){const names=f===2?['楼梯 A','男卫','管井','通信机房','监控室','女卫','技术办公','资料室','会议室','控制室','检修间','设备支持','开放办公','通信机柜','值班室','楼梯 B']:['楼梯 A','男卫','管井','设备机房','办公室','女卫','资料室','洽谈室','会议室','办公室','档案室','设备支持','综合办公','办公室','休息室','楼梯 B'];const cells=[[64,34,150,111],[229,34,146,111],[390,34,146,111],[555,34,144,111],[64,164,150,50],[229,164,146,50],[390,164,146,50],[555,164,144,50],[64,296,150,50],[229,296,146,50],[390,296,146,50],[555,296,144,50],[64,365,150,111],[229,365,146,111],[390,365,146,111],[555,365,144,111]];let s=`<svg xmlns="http://www.w3.org/2000/svg" width="768" height="512" viewBox="0 0 768 512"><rect width="768" height="512" fill="white"/><rect x="60" y="30" width="648" height="454" fill="#eef4f6" stroke="#1e394c" stroke-width="4"/><rect x="63" y="224" width="642" height="64" fill="white"/>`;cells.forEach((r,i)=>{s+=`<rect x="${r[0]-3}" y="${r[1]-5}" width="${r[2]+12}" height="${r[3]+12}" fill="none" stroke="#335268" stroke-width="2"/>`;if(i===0||i===15){for(let j=0;j<13;j++)s+=`<path d="M ${r[0]+23} ${r[1]+15+j*5}h90" stroke="#7695a5" stroke-width=".8"/>`;s+=`<path d="M${r[0]+66} ${r[1]+13}v73" stroke="#638998"/>`}else if(r[3]>100){for(let j=0;j<3;j++)s+=`<rect x="${r[0]+13+j*41}" y="${r[1]+13}" width="25" height="65" fill="#fafdfb" stroke="#91a7b1"/>`}else{s+=`<rect x="${r[0]+22}" y="${r[1]+10}" width="90" height="10" fill="white" stroke="#91a7b1"/><rect x="${r[0]+33}" y="${r[1]+26}" width="21" height="9" fill="white" stroke="#91a7b1"/>`}let cy=r[1]+(r[3]>100?63:31);s+=`<rect x="${r[0]+r[2]/2-40}" y="${cy-10}" width="80" height="20" fill="white" opacity=".95"/><text x="${r[0]+r[2]/2}" y="${cy+4}" text-anchor="middle" font-family="sans-serif" font-size="12" fill="#324f62">${names[i]}</text>`;if(i<8)s+=`<path d="M${r[0]+35} ${r[1]+r[3]+7}h28" stroke="white" stroke-width="5"/>`;else s+=`<path d="M${r[0]+35} ${r[1]-5}h28" stroke="white" stroke-width="5"/>`});[139,301,465,627].forEach(x=>s+=`<text x="${x}" y="259" text-anchor="middle" font-family="sans-serif" font-size="12" fill="#456072">公共走廊</text>`);s+='</svg>';return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(s)}
