function createProject(name,sample=false,variant=0){const pr={id:uid('project'),name,sample,assets:{},versions:[],events:[],runs:[],results:[],undo:[],redo:[],currentFloor:'F01',created:now(),updated:now()};const floors={};if(sample){for(let i=1;i<=(variant?2:3);i++){const aid='asset'+i;pr.assets[aid]={id:aid,name:i===1&&!variant?'P2 示例预览.webp':`程序绘制_${i}F_演示.svg`,url:i===1&&!variant?SAMPLE_URL:synthetic(i===1?2:i),width:768,height:512,sample:true,provenance:i===1&&!variant?'来自用户提供的 P2 图的同尺寸压缩预览；1F 仅为演示分配':'程序绘制的楼层演示图，非用户实际楼层图'};floors['F0'+i]={label:i+'F',name:['设备与运维','控制与技术','办公与支持'][i-1],assetId:aid,items:variant?[]:presetItems(i)}}}pr.versions.push({id:'r0',parent:null,title:sample?'导入演示图纸':'创建空项目',created:now(),floors});event(pr,'project.created','创建'+(sample?'演示':'空')+'项目',{sample,modelExecuted:false});return pr}
function seed(){state.projects=[createProject('发电厂辅助用房',true),createProject('运行管理附楼',true,1),createProject('新建重建项目')];saveSoon()}
async function openDB(){return new Promise((resolve,reject)=>{try{const req=indexedDB.open('AutoPlanP3CanvasV3',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspaces');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}catch(e){reject(e)}})}
function saveSoon(){clearTimeout(persistTimer);if($('saveStatus'))$('saveStatus').textContent=db?'保存中…':'临时会话';persistTimer=setTimeout(persist,170)}
async function persist(){if(!db){$('saveStatus').textContent='临时会话 · 可导出';return}try{const snap=clone(state);await new Promise((resolve,reject)=>{const tx=db.transaction('workspaces','readwrite');tx.objectStore('workspaces').put(snap,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});$('saveStatus').textContent='已保存到本浏览器'}catch(e){$('saveStatus').textContent='保存失败 · 请导出';toast('浏览器保存失败，请通过更多菜单导出工程备份。',true)}}
function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function exportProject(){if(!p())return;download(new Blob([JSON.stringify({schema:SCHEMA,exported:now(),purpose:'INTERACTION_ONLY',modelExecuted:false,project:p()},null,2)],{type:'application/json;charset=utf-8'}),'P3_标注工程_'+head().id+'.json');toast('已导出标注工程；包含本地图片，请妥善保存。')}

async function importProject(file){if(job)return;try{if(file.size>40*1024*1024)throw new Error('工程文件超过 40 MB');if(state.projects.length>=limits.projects)throw new Error('项目数量已达上限');const data=JSON.parse(await file.text()),pr=data.project;if(data.schema!==SCHEMA||data.modelExecuted!==false||!pr||!Array.isArray(pr.versions)||!pr.versions.length||pr.versions.length>limits.versions||!pr.assets||Array.isArray(pr.assets))throw new Error('不是本原型支持的标注工程');const validKey=k=>typeof k==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(k)&&!['__proto__','constructor','prototype'].includes(k);if(typeof pr.name!=='string'||pr.name.length>80)throw new Error('项目名称无效');const safeSVG=[synthetic(2),synthetic(3)];let count=0;for(const [id,a] of Object.entries(pr.assets)){if(!validKey(id)||++count>100||typeof a.url!=='string'||a.url.length>18*1024*1024||(!/^data:image\/(png|jpeg|webp);base64,/.test(a.url)&&!safeSVG.includes(a.url)))throw new Error('工程含不允许的图片引用');const im=await img(a.url);if(im.naturalWidth!==a.width||im.naturalHeight!==a.height||a.width*a.height>limits.pixels)throw new Error('图片尺寸不一致');a.sample=a.url===SAMPLE_URL||safeSVG.includes(a.url);if(typeof a.name!=='string'||a.name.length>200)throw new Error('图片名称无效')}
for(let i=0;i<pr.versions.length;i++){const r=pr.versions[i];if(r.id!=='r'+i||r.parent!==(i?'r'+(i-1):null)||typeof r.title!=='string'||r.title.length>200||!r.floors||Object.keys(r.floors).length>limits.floors)throw new Error('版本链不完整');if(r.restoredFrom&&!pr.versions.slice(0,i).some(v=>v.id===r.restoredFrom))throw new Error('恢复来源不存在');for(const [fid,f] of Object.entries(r.floors)){if(!validKey(fid)||!validKey(f.assetId)||!pr.assets[f.assetId]||typeof f.label!=='string'||f.label.length>20||typeof f.name!=='string'||f.name.length>80||!Array.isArray(f.items)||f.items.length>limits.objects)throw new Error('楼层数据无效');const seen=new Set(),a=pr.assets[f.assetId];for(const o of f.items){if(!validKey(o.id)||seen.has(o.id)||!['manual','preset'].includes(o.source)||!['pending','candidate','confirmed'].includes(o.status)||!['type','label','note'].every(k=>typeof o[k]==='string'&&o[k].length<=500)||!Array.isArray(o.rect)||o.rect.length!==4||!o.rect.every(Number.isFinite))throw new Error('标注格式无效');seen.add(o.id);const [x,y,w,h]=o.rect;if(x<0||y<0||w<8||h<8||x+w>a.width+.1||y+h>a.height+.1)throw new Error('标注越界')}}}
pr.id=uid('imported');pr.name=pr.name.slice(0,72)+'（导入）';pr.sample=Object.values(pr.assets).length>0&&Object.values(pr.assets).every(a=>a.sample);pr.currentFloor=Object.keys(pr.versions.at(-1).floors)[0]||'F01';pr.undo=[];pr.redo=[];pr.runs=[];pr.results=[];pr.events=(Array.isArray(pr.events)?pr.events:[]).filter(e=>e&&typeof e.type==='string'&&typeof e.text==='string'&&e.text.length<500&&Number.isFinite(Date.parse(e.time))).slice(-500);state.projects.unshift(pr);event(pr,'project.imported','导入工程为独立项目',{modelExecuted:false,importedVersions:pr.versions.length,resultsNotTrusted:true});saveSoon();enterProject(pr.id);toast('工程已恢复为独立项目。旧项目未覆盖，未沿用结果审批。')}catch(e){toast('工程导入失败：'+e.message,true)}}
